#include <iostream>

#include <list>

#include <string>

using namespace std;

struct Entry {

    string key, value;

};

class HashTableChaining {

private:

    list<Entry>* table;

    int tableSize;



    int hash(const string& key) {

        int h = 0;

        for (char c : key) h = h * 31 + c;

        return abs(h) % tableSize;

    }



public:

    HashTableChaining(int size) : tableSize(size) {

        table = new list<Entry>[size];

    }



    void insert(const string& key, const string& value) {

        int idx = hash(key);

        for (auto& e : table[idx]) {

            if (e.key == key) {

                e.value = value;

                return;

            }

        }

        table[idx].push_back({key, value});

    }



    string search(const string& key) {

        int idx = hash(key);

        for (auto& e : table[idx]) {

            if (e.key == key) return e.value;

        }

        return "";

    }

};

