        self.table_size = size

        self.table = [[] for _ in range(size)]



    def hash(self, key):

        return hash(key) % self.table_size



    def insert(self, key, value):

        idx = self.hash(key)

        # Update if exists

        for entry in self.table[idx]:

            if entry[0] == key:

                entry[1] = value

                return

        # Add new entry

        self.table[idx].append([key, value])



    def search(self, key):

        idx = self.hash(key)

        for k, v in self.table[idx]:

            if k == key:

                return v

        return None



    def delete(self, key):

        idx = self.hash(key)

        self.table[idx] = [(k, v) for k, v in self.table[idx] 

                           if k != key]

