class HashTableChaining {

    constructor(size) {

        this.tableSize = size;

        this.table = Array(size).fill().map(() => []);

    }



    hash(key) {

        let h = 0;

        for (let i = 0; i < key.length; i++) {

            h = h * 31 + key.charCodeAt(i);

        }

        return Math.abs(h) % this.tableSize;

    }



    insert(key, value) {

        const idx = this.hash(key);

        // Update if exists

        for (let entry of this.table[idx]) {

            if (entry[0] === key) {

                entry[1] = value;

                return;

            }

        }

        // Add new entry

        this.table[idx].push([key, value]);

    }



    search(key) {

        const idx = this.hash(key);

        for (let [k, v] of this.table[idx]) {

            if (k === key) return v;

        }

        return null;

    }



    delete(key) {

        const idx = this.hash(key);

        this.table[idx] = this.table[idx].filter(

            entry => entry[0] !== key

        );

    }

}

